local Players = game:GetService("Players")
local module = {}

local scopeCache = {}
setmetatable(scopeCache, {
	__mode = "v",
})

local logger: ILogger = nil
local services = nil
local cancellationTokenProvider: IPlayerScopeCancellationTokenProvider = nil

-- 检查玩家作用域是否准备好
module.IsPlayerReady = function(playerOrUserId: Player | number)
	if typeof(playerOrUserId) ~= "number" then
		playerOrUserId = playerOrUserId.UserId
	end

	local scope = scopeCache[playerOrUserId]
	if not scope then
		return false
	end

	return true
end

local function onPlayerRemoving(player: Player)
	local cancellationToken = cancellationTokenProvider:GetCancellationToken(player.UserId)
	cancellationToken.isPlayerRemoved = true

	-- 销毁作用域
	local scope = scopeCache[player.UserId] :: IServiceScope
	scopeCache[player.UserId] = nil
	if scope then

		local PlayerHostedAsyncServiceManager = scope:GetRequiredService("PlayerHostedAsyncServiceManager")
		PlayerHostedAsyncServiceManager:Stop()

		local playerHostedServiceManager = scope:GetRequiredService("PlayerHostedServiceManager")
		playerHostedServiceManager:Stop()

		if not scope._disposed then
			logger.verbose(function(name)
				print(name, player.UserId, " dispose scope on player removing")
			end)
			scope:Dispose()
		end
	end
	cancellationTokenProvider:RemoveCancellationToken(player.UserId)
end

local function onPlayerAdded(player: Player)
	-- 客户端不处理非本地玩家
	if game:GetService("RunService"):IsClient() then
		if player.UserId ~= game.Players.LocalPlayer.UserId then
			return
		end
	end

	logger.verbose(function(name)
		print(name, player.UserId, "Player Added")
	end)

	-- set cancellationToken
	local cancellationToken = cancellationTokenProvider:GetCancellationToken(player.UserId)

	local scope = services:CreateScope()

	-- 尝试销毁作用域
	local function tryDisposeScope(): boolean
		if cancellationToken:IsCancelled() then
			logger.verbose(function(name)
				print(name, player.UserId, "scope disposed on player leave before scope ready")
			end)
			if not scope._disposed then
				scope:Dispose()
			end
			return true
		end
		return false
	end

	local tsPlayerProvider = scope:GetRequiredService("ITangSengPlayerProvider")
	assert(not tsPlayerProvider:GetPlayer(), "TangSengPlayerProvider.Player is already set")
	tsPlayerProvider:SetPlayer(player)

	
	logger.verbose(function(name)
		print(name, player.UserId, "start player scope")
	end)

	-- playerHostedAsyncService
	local playerHostedAsyncServiceManager = scope:GetRequiredService("PlayerHostedAsyncServiceManager")

	-- 如果玩家已经离开，则直接销毁作用域
	if tryDisposeScope() then
		return
	end

	-- playerHostedService
	local playerHostedServiceManager = scope:GetRequiredService("PlayerHostedServiceManager")

	-- 如果玩家已经离开，则直接销毁作用域
	if tryDisposeScope() then
		return
	end

	scopeCache[player.UserId] = scope

	-- 启动服务
	playerHostedAsyncServiceManager:Start(cancellationToken)
	playerHostedServiceManager:Start(cancellationToken)


	-- 如果玩家已经离开，则直接销毁作用域
	if tryDisposeScope() then
		scopeCache[player.UserId] = nil
		return
	end

	cancellationToken.isScopeStarted = true
	logger.verbose(function(name)
		print(name, player.UserId, "start player scope success")
	end)
end


module.Init = function(
	serviceProvider: IServiceProvider,
	loggerManager: ILoggerManager,
	tokenProvider: IPlayerScopeCancellationTokenProvider
)
	cancellationTokenProvider = tokenProvider
	logger = loggerManager.GetLogger("PlayerScopeService")
	logger.verbose(function(name)
		print(name, "Success Init")
	end)

	services = serviceProvider

	game.Players.PlayerAdded:Connect(onPlayerAdded)

	game.Players.PlayerRemoving:Connect(onPlayerRemoving)


	for k, v in game.Players:GetPlayers() do
		task.spawn(function()
			onPlayerAdded(v)
		end)
	end
end

module.GetPlayerScope = function(playerOrUserId: (Player | number)?): IServiceScope
	-- 如果是客户端且参数为空，则认为是当前玩家
	if not playerOrUserId then
		if game:GetService("RunService"):IsClient() then
			playerOrUserId = game.Players.LocalPlayer
		else
			error("playerOrUserId is nil (only allowed on client)")
		end
	end

	if typeof(playerOrUserId) ~= "number" then
		playerOrUserId = playerOrUserId.UserId
	end
	return scopeCache[playerOrUserId]
end

module.GetServiceInPlayerScope = function(playerOrUserId: (Player | number)?, serviceType: string)
	local scope = module.GetPlayerScope(playerOrUserId)
	return scope:GetService(serviceType)
end

module.GetRequiredServiceInPlayerScope = function(playerOrUserId: (Player | number)?, serviceType: string)
	local scope = module.GetPlayerScope(playerOrUserId)
	return scope:GetRequiredService(serviceType)
end

module._innerOnPlayerAdded = function(player: Player)
	onPlayerAdded(player)
end

module._innerGetCache = function()
	return scopeCache
end

module._innerOnPlayerRemoving = function(player: Player)
	onPlayerRemoving(player)
end

return module
